import {solanaMarket} from './onepill-market.mjs';
import {safeText as e,formatUnits} from './api.mjs';
const chains=[['ethereum','Ethereum','ETH'],['base','Base','ETH'],['bsc','BNB Chain','BNB'],['robinhood','Robinhood Chain','ETH'],['solana','Solana','SOL']];
let evmProvider=null,evmWallet='',busy=false;
const provider=()=>window.phantom?.ethereum??window.ethereum;
const post=(api,action,body)=>api.request('/launch/onepill/'+action,{method:'POST',body,signal:AbortSignal.timeout(30000)});
export function onepillCard(c){return `<article class="coin-card classic-coin"><a class="coin-image" href="#onepill/${e(c.id)}"><img class="art" src="${e(c.image||'/assets/pill-v1.svg')}" alt=""></a><div class="coin-copy"><div class="tags"><span class="tag onepill-tag">onepill mode</span><span class="tag">5 chains</span></div><p><a href="#onepill/${e(c.id)}"><strong>${e(c.name)} (ticker: ${e(c.symbol)})</strong></a></p><p>${e(c.description||'')}</p><p class="note">ETH · BASE · BNB · RH · SOL</p><small>Powered by <a class="pangea-brand" href="https://www.pangea.trade" target="_blank" rel="noopener noreferrer"><img src="/assets/pangea-mark.svg" width="18" height="18" alt="">Pangea</a></small></div></article>`;}
export function onepillForm(){let draft={};try{draft=JSON.parse(sessionStorage.getItem('pill-onepill-draft')||'{}')}catch{};return `<form id="onepill-form" class="panel onepill-form"><div class="onepill-heading"><span class="tag onepill-tag">onepill mode</span><h1>One coin. Five chains.</h1><p>Powered by <a class="pangea-brand" href="https://www.pangea.trade" target="_blank" rel="noopener noreferrer"><img src="/assets/pangea-mark.svg" width="18" height="18" alt="">Pangea</a></p></div><div class="onepill-chains">${chains.map(([,name])=>`<span class="tag">${name}</span>`).join('')}</div><div class="field-grid"><label class="field"><span>Name</span><input name="name" maxlength="32" value="${e(draft.name||'')}" required></label><label class="field"><span>Ticker</span><input name="symbol" value="${e(draft.symbol||'')}" maxlength="10" pattern="[A-Za-z0-9]{1,10}" required></label></div><label class="field"><span>Picture</span><input name="picture" type="file" accept="image/png,image/jpeg,image/webp" required><small>PNG, JPG or WebP · up to 4 MB. Uploaded to public IPFS for your Pangea launch.</small></label><label class="field"><span>Description</span><textarea name="description" maxlength="2000">${e(draft.description||'')}</textarea></label><div class="field"><span>Trading fee · every chain</span><strong>1% · fixed</strong></div><div class="receipt"><div><span>Pairs</span><strong>ETH · BNB · SOL</strong></div><div><span>Launch payment</span><strong>ETH on Base · live quote</strong></div><div><span>Creator fees</span><strong>Your connected wallets</strong></div></div><p class="note">Connect your Solana wallet and an EVM wallet. Both confirm ownership; your EVM wallet pays the launch fee on Base. Standard launch only, with native-coin pairs.</p><div class="row"><button type="button" data-action="wallet">Connect Solana wallet</button><button type="button" data-onepill="connect">${evmWallet?e(evmWallet.slice(0,6)+'…'+evmWallet.slice(-4)):'Connect EVM wallet'}</button></div><button class="primary wide" type="submit">Review five-chain launch</button><button type="button" class="subtle wide" data-onepill="mine">[my OnePill launches]</button><div id="onepill-feedback" class="error" role="status"></div></form>`;}
export function onepillStatus(c){const live=c.status?.result?.live??{},complete=c.state==='done';return `<section class="panel onepill-detail"><span class="tag onepill-tag">onepill mode</span>${c.image?`<img src="${e(c.image)}" alt="" width="80" height="80" style="object-fit:cover;margin:16px 0">`:''}<h1>${e(c.name)} <small>$${e(c.symbol)}</small></h1><p>Powered by <a class="pangea-brand" href="https://www.pangea.trade" target="_blank" rel="noopener noreferrer"><img src="/assets/pangea-mark.svg" width="18" height="18" alt="">Pangea</a> · ${e(c.state.replaceAll('_',' '))}</p><p class="note">Trading fee: ${(c.feeBps/100).toFixed(2)}%. Native-coin pairs across five chains. ${complete?'All five pools are live.':'Each chain appears below as Pangea confirms it.'}</p>${complete&&c.chains?.solana?.token?solanaMarket(c):''}<details><summary>All five chains</summary><div class="onepill-chain-list">${chains.map(([key,name,asset])=>{const token=c.chains?.[key]?.token??live[key]?.token;return `<div><strong>${name} <small>/${asset}</small></strong><span>${token?'Live':'Waiting'}</span>${token?`<code>${e(token)}</code><a href="https://www.pangea.trade/app/t/${encodeURIComponent(token)}" target="_blank" rel="noopener noreferrer">[trade on Pangea]</a>`:''}</div>`}).join('')}</div></details>${c.status?.lastError?`<p class="error">${e(String(c.status.lastError))}</p>`:''}${!complete?`<button data-onepill="resume" data-id="${e(c.id)}">Check launch / resume submission</button>`:''}<p class="note">The five-chain supply and prices follow Pangea’s rules. This mode has no Pill bonding curve or PumpSwap graduation.</p><a href="https://www.pangea.trade/app/launch" target="_blank" rel="noopener noreferrer">[Pangea launch support & refunds]</a></section>`;}
export async function connectEvm(){evmProvider=provider();if(!evmProvider?.request)throw Error('Open an EVM wallet such as MetaMask or Phantom to connect.');const accounts=await evmProvider.request({method:'eth_requestAccounts'});if(!/^0x[0-9a-f]{40}$/i.test(accounts?.[0]??''))throw Error('No EVM account was connected.');evmWallet=accounts[0];return evmWallet;}
async function assertEvm(expected){if(!evmProvider)await connectEvm();const accounts=await evmProvider.request({method:'eth_accounts'});if(accounts?.[0]?.toLowerCase()!==expected.toLowerCase())throw Error('Reconnect the EVM wallet used for this quote.');}
export async function quoteOnepill(api,form,solWallet){if(!solWallet)throw Error('Connect your Solana wallet first.');if(!evmWallet)await connectEvm();await assertEvm(evmWallet);const picture=form.get('picture');if(!picture?.size||picture.size>4*1024*1024)throw Error('Choose a PNG, JPG or WebP image up to 4 MB.');
const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read the picture.'));reader.readAsDataURL(picture);});
const uploaded=await api.request('/launch/onepill/media',{method:'POST',body:{name:form.get('name'),symbol:form.get('symbol'),description:form.get('description'),image},signal:AbortSignal.timeout(100000)});
return post(api,'prepare',{requestId:crypto.randomUUID(),name:form.get('name'),symbol:form.get('symbol'),metadataURI:uploaded.uri,feeBps:100,creatorEvm:evmWallet});}
export function reviewOnepill(record){const q=record.quote;return `<h3>${e(record.name)} · $${e(record.symbol)}</h3><div class="onepill-chains">${chains.map(([,name])=>`<span class="tag">${name}</span>`).join('')}</div><div class="receipt"><div><span>Trading fee</span><strong>${(record.feeBps/100).toFixed(2)}%</strong></div><div><span>Launch fee · ETH on Base</span><strong>${e(formatUnits(q.fee.payment.send,18,8))} ETH</strong></div><div><span>Quoted USD</span><strong>$${Number(q.fee.feeUsd).toFixed(2)}</strong></div></div><p class="notice">Your wallets first sign ownership messages, then your EVM wallet approves the launch payment. Base network gas is additional. The quote expires ten minutes after it is issued. Pangea’s ownership messages use Pangea branding; verify the coin, wallets and launch ID before signing. Fees go to your connected creator wallets according to Pangea’s split.</p><button class="primary wide" data-onepill="pay" data-id="${e(record.id)}">Confirm ownership & pay in wallet</button><div id="onepill-feedback" class="error" role="status"></div>`;}
export async function payOnepill(api,record,solProvider){
 if(busy)throw Error('A launch approval is already in progress.');busy=true;
 try{
  const q=record.quote,owner=q.payerProof.signer;await assertEvm(owner);
  if(solProvider?.publicKey?.toString()!==record.creator)throw Error('Reconnect the Solana wallet used for this quote.');
  const auth={id:record.id};
  for(const [proof,key] of [[q.payerProof,'payerAuth'],...(q.creatorProofs??[]).map(p=>[p,p.side==='solana'||p.side==='sol'?'creatorSolAuth':'creatorEvmAuth'])]){
   if(typeof proof.message!=='string'||!proof.message.toLowerCase().includes(record.id.toLowerCase()))throw Error('Unexpected ownership message from Pangea.');
   if(proof.signer.toLowerCase()===owner.toLowerCase()){
    await assertEvm(owner);const hex='0x'+Array.from(new TextEncoder().encode(proof.message),b=>b.toString(16).padStart(2,'0')).join('');auth[key]=await evmProvider.request({method:'personal_sign',params:[hex,owner]});
   }else if(proof.signer===record.creator){const signed=await solProvider.signMessage(new TextEncoder().encode(proof.message),'utf8');const bytes=signed.signature??signed;auth[key]='0x'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
   else throw Error('Pangea requested a signature from an unexpected wallet.');
  }
  await post(api,'authorize',auth);
  await evmProvider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x2105'}]});await assertEvm(owner);
  if(Number(await evmProvider.request({method:'eth_chainId'}))!==8453)throw Error('Switch your EVM wallet to Base.');
  const payment=await post(api,'pay',{id:record.id});
  // Server has already checked collector, amount, payer and chain against the stored ticket.
  let hash;
  try{hash=await evmProvider.request({method:'eth_sendTransaction',params:[{from:payment.from,to:payment.tx.to,data:payment.tx.data,value:'0x'+BigInt(payment.tx.value).toString(16),chainId:'0x2105'}]});}
  catch(error){if(error.code===4001)await post(api,'rejected',{id:record.id});else error.message='Payment status is uncertain. Open My OnePill launches to check it; do not pay again. '+error.message;throw error;}
  localStorage.setItem('pill-onepill-payment-'+record.id,hash);
  await post(api,'payment',{id:record.id,hash});
  return {id:record.id,hash};
 }finally{busy=false;}
}
export async function resumeOnepill(api,id){try{await post(api,'submit',{id})}catch(error){if(error.status!==402)throw error;}return api.request('/launch/onepill/status?id='+encodeURIComponent(id));}
